#include "Application.hpp"
#include <ctime>
#include "../game/VictoryDialogue.hpp"
namespace th075::sdl {
void Application::sound(i16 id){audio.sound(id);}void Application::character_sound(u8 side,i16 id){audio.character_sound(side,id);}void Application::fade_music(i32 target,i32 step,u32 stop,u32 start){audio.fade_music(target,step,u8(stop),u8(start));}void Application::select_music(i16 cue){if(!audio.select_music(cue))error=audio.error;else if(cue>=0&&(!battle||(battle->session.replayMode!=2&&battle->session.replayMode!=4)))profile.unlock(i16(cue+100));}void Application::start_music(){audio.start_music();}void Application::start_music(i32 volume){audio.music_level(volume);}void Application::stop_music(){audio.stop_music();}void Application::stop_music(i32 cue){select_music(i16(cue));}
void Application::music_volume(u8 n){audio.musicVolume=n;audio.music_level(0);}void Application::sound_volume(u8 n){audio.soundVolume=n;}
void Application::origin(float x,float y,bool box){textSurface.configure(x,y,box);}void Application::text(const std::string& value,u8 r,u8 g,u8 b,u32 height,u8 part,bool continuation){const auto o=textSurface.begin(u8(height),r,g,b,part,continuation);if(!fonts.write(dialogueTexture,value,o))error=fonts.error;}void Application::render(){ImageRenderer images(zun,windowImages);textSurface.render(images,dialogueTexture);}
void Application::reload_stage(u8 background){selection.background=background;loading.story.background=background;if(battle)battle->simulation.story.background=background;BackgroundKind kind;if(!battleRenderer||!choose_background(background,settings.animatedBackground!=0,kind)){error="Invalid story background";return;}battleRenderer->background.reset(kind);load_images(stageImages,ResourceEdition::Base,battleRenderer->background.resource_path());}
void Application::dialogue_origin(float x,float y,u32 mode){origin(x,y,mode!=0);}void Application::prepare_victory(RoundFighterState& winner){if(battle){const u8 side=battle->simulation.rules.winner;select_victory_dialogue(winner,characterAssets[side].script,selection.character[1-side],battle->simulation.replay.random);}}void Application::show_victory_line(const std::string& value,u8){text(value,120,120,255,24,5,false);}void Application::end_story_dialogue(){text("",120,120,255,16,1,false);}void Application::render_before_story_load(){if(battle)battle->render();}void Application::release_battle_loader(){}void Application::stage_story_completed(){if(captureTexture)graphics.destroy(captureTexture);captureTexture=graphics.snapshot();}
void Application::reset_fighter(u32,RoundFighterState&){}void Application::reset_stage_effects(){if(battleRenderer)battleRenderer->background.reset(battleRenderer->background.kind);}void Application::advance_overlay(){if(battleRenderer&&battle)battleRenderer->advance_overlay(battle->progress);}void Application::banner(bool ko){if(battleRenderer&&battle)battleRenderer->begin_overlay(ko,battle->progress);}void Application::combo(u8 side,i16 hits,i16 damage,i32 scale){if(battleRenderer)battleRenderer->combo(side,hits,damage,scale);}void Application::spell_attempt(u8 side,u8 card){if(side==1&&battle&&card<battle->simulation.rules.storyCards.size())++battle->simulation.rules.storyCards[card].attempts;}void Application::advance_stage(){if(battleRenderer)battleRenderer->background.advance();}
void Application::render_battle(BattleScene& b,bool display){graphics.clear(0x0f000000);if(battleRenderer)battleRenderer->render(b,display,now);}void Application::present_battle(){graphics.present();}void Application::toggle_fullscreen(){auto* window=SDL_GL_GetCurrentWindow();if(window)SDL_SetWindowFullscreen(window,!(SDL_GetWindowFlags(window)&SDL_WINDOW_FULLSCREEN));}
void Application::ResetEvents::clear_owned_objects(FighterActor&){if(app.battle)app.battle->simulation.objects[side].clear();}void Application::ResetEvents::spell_attempt(u8 card){app.spell_attempt(side,card);}void Application::ResetEvents::reset_hud_alpha(){app.loading.story.hudAlpha={255,255};}FighterCoreEvents& Application::reset_events(u8 side){return resetEvents[side];}
void Application::save_profile(const std::vector<u8>& b){if(!FileResources::write_file("/save/score.dat",b.data(),u32(b.size())))error="Unable to save profile";}
bool Application::load_character(u8 side,const CharacterDefinition& d,u8 palette,CharacterController& c){audio.release_character(side);characterAssets[side]=CharacterAssets{};auto& a=characterAssets[side];if(!a.load(resources,d,palette)){error=a.error;return false;}c.actor.animation.pattern=&a.pattern;if(!characterImages[side]->load(a.sprites)||!portraitImages[side]->load(a.portraits)||!audio.character_bank(side,a.sounds)){error=graphics.error+audio.error;return false;}return true;}
void Application::load_story_artwork(CharacterController&,u8 stage){const auto* d=character_definition(selection.character[0]);if(!d)return;if(!characterAssets[0].load_story(resources,*d,stage)||!captionImages[0]->load(characterAssets[0].story)){error=characterAssets[0].error+graphics.error;return;}if(battleArt)for(u8 i=0;i<4;i++)battleArt->captions[0][i]=captionImages[0]->image(i).texture;}
void Application::prepare_round_recording(const GameSelection& selected,const BattleSession&,const RoundRules& rules,const FighterActor& player){if(recording.rounds.size()>=8)return;recording.rounds.emplace_back();ReplayConfiguration::record(recording,recording.rounds.back(),selected,playerSettings,rules,player);recording.header[14]=u8(recording.rounds.size());const auto date=std::time(nullptr);const auto* tm=std::localtime(&date);recording.header[8]=u8(tm->tm_mon+1);recording.header[9]=u8(tm->tm_mday);saveReplayOpponent=selected.character[1-selected.activePlayer];loadingReplay.bind(ReplayMode::Recording,&recording.rounds.back(),loadingReplay.random.state);recordingFinished=false;}
void Application::begin_round_recording(){fade_music(-6000,-200,1,1);}void Application::finish_replay_round(){if(battle)loadingReplay=battle->simulation.replay;recordingFinished=true;if(battle)pendingSession=battle->session;}
bool Application::load_battle(){if(battle){pendingSession=battle->session;pendingRules=battle->simulation.rules;loadingReplay=battle->simulation.replay;loading.story=battle->simulation.story;}battleRenderer.reset();battleArt.reset();battle.reset();if(pendingSession.replayMode==2){const u32 index=playbackCursor++;if(!ReplayConfiguration::load(playback,index,selection,playerSettings,pendingRules,loadingReplay)){error="Replay round unavailable";return false;}if(playback.header[13]>=5){selection.storyStage=u8(index+1);pendingSession.roundIndex=i8(index+1);}}else pendingSession.replayMode=1;
 if(pendingSession.roundIndex==0)for(u8 a=0;a<11;a++)for(u8 b=0;b<11;b++)pendingSession.victories[a][b]=i32(profile.victories[a][b]);
 if(!loading.load(selection,settings,playerSettings,profile,loadingReplay,pendingSession,pendingRules,*this)){error=loading.error;return false;}battle=std::make_unique<BattleScene>(loading.controllers(),effects,*this);// Install loaded story state before initialize clears cinematic overrides for non-story modes.
 battle->simulation.story=loading.story;battle->initialize(pendingSession);const auto initial=battle->simulation.rules.phase;battle->simulation.rules=pendingRules;battle->simulation.rules.phase=initial;battle->simulation.rules.countdown=200;battle->simulation.difficulty=selection.difficulty;battle->simulation.replay=loadingReplay;battle->simulation.replayMode=battle->session.replayMode;battle->timing.renderEveryFrame=settings.renderEveryFrame!=0;dialogueCache={};
 battleArt=std::make_unique<BattleArtwork>(BattleArtwork{stageImages,hudImages,effectImages});for(u8 s=0;s<2;s++){battleArt->fighters[s]=characterImages[s].get();battleArt->portraits[s]=portraitImages[s].get();battleArt->fighterTextures[s]=characterImages[s]->handles;for(u8 i=0;i<4;i++)battleArt->captions[s][i]=captionImages[s]->image(i).texture;}battleRenderer=std::make_unique<BattleRenderer>(zun,*battleArt,*this);BackgroundKind kind;if(!choose_background(selection.background,settings.animatedBackground!=0,kind)){error="Invalid background";return false;}battleRenderer->background.reset(kind);if(!load_images(stageImages,ResourceEdition::Base,battleRenderer->background.resource_path()))return false;battleRenderer->recoveryMarkers=settings.recoveryMarkers!=0;if(selection.mode!=GameMode::Story){select_music(selection.background);start_music();}return error.empty();}
}
